    ('9d7f44cd-a199-5547-a5c2-f637a337a375'::uuid, 'Quiz — Multiplier toujours par le même nombre', 'Ens. scientifique', '1re', 'Croissance exponentielle et suites géométriques', '575522c0-2cd9-55fd-b514-1937eca8c56b'::uuid),
    ('ef7b0334-d7f8-5a17-9b15-2e1579a1faf5'::uuid, 'Quiz — La courbe qui s’envole, version continue', 'Ens. scientifique', '1re', 'Croissance et fonctions exponentielles', '7e3275e2-b9a6-55c7-af3a-5d44b0c90157'::uuid),
